def transform(grid):
    h=len(grid); w=len(grid[0])
    first=next((x for row in grid for x in row if x not in (0,8)),None)
    end=max((r for r,row in enumerate(grid) if first in row),default=-1)
    return [[8 if x==8 and r>end else 0 for x in row] for r,row in enumerate(grid)]

